"""GENERATED by eda/169_candidate_wx.py: eda/20b + the D159 features (cart ramp, LLM scores, temperature, events). Do not edit by hand."""
"""Quantile model for the 4-month total per item, backtested on the 13 rolling origins.
Target: z = log((total of next 4 months + 1) / (4 x level + 1)), one row per item x origin (horizon fixed at the 4-month total).
Quantile LightGBM at 7 levels, two feature sets averaged per level (Vincentization), quantiles sorted to remove crossing.
Outputs data/q_backtest.parquet: per item x origin the quantiles (in units), the actual total and the current point model's total."""
import pandas as pd, numpy as np, lightgbm as lgb, warnings, time, sys
warnings.filterwarnings("ignore")
QS = [0.10, 0.25, 0.40, 0.50, 0.60, 0.75, 0.90]
F = pd.read_parquet("data/features.parquet")
for c in ["ptype", "macro"] + [c for c in F.columns if c.startswith("a_")]: F[c] = F[c].astype("category")
OCC = [c for c in F.columns if c.startswith("occ_")]
# seasonal-ratio features averaged over the 4 target months, so the total-level row sees the whole window
g = F.groupby(["origin", "style_color"])[["lfl_type", "lfl_macro", "lfl_occ", "own_sea"]].mean().add_suffix("4").reset_index()
T1 = F[F.h == 1].drop(columns=["y", "h"]).merge(g, on=["origin", "style_color"])
T1["z"] = np.log((T1.ytot + 1) / (4 * T1.level + 1))
BASE = [f"lagr{k}" for k in range(1, 7)] + ["lvl", "age_m", "ptype", "tmonth", "color_num", "own_sea4"] + OCC
FULL = BASE + ["f_r7", "f_r28", "trend91", "peak_r", "days_live", "sh_ret", "sh_drop", "sh_tt", "disc_item", "disc_rel", "lfl_type4", "lfl_macro4", "lfl_occ4"] + [c for c in F.columns if c.startswith("a_")]
P = dict(n_estimators=300, learning_rate=0.05, num_leaves=15, min_child_samples=40, subsample=0.8, subsample_freq=1, colsample_bytree=0.8, reg_lambda=5, verbose=-1, random_state=0, n_jobs=4)

# --- lean set + occasion timing (D134/D135) ---
_DROP = lambda c: c in ("age_m", "days_live", "color_num", "sh_ret", "sh_drop", "sh_tt", "disc_item", "disc_rel") or c.startswith("occ_")
BASE = [c for c in BASE if not _DROP(c)]; FULL = [c for c in FULL if not _DROP(c)]
_CF = pd.read_parquet("data/context_feats.parquet")[["origin", "style_color", "occ_next", "occ_last", "occ_n4"]]
T1 = T1.merge(_CF, on=["origin", "style_color"], how="left"); BASE += ["occ_next", "occ_last", "occ_n4"]; FULL += ["occ_next", "occ_last", "occ_n4"]

# --- D159 features: cart ramp + LLM scores + temperature + events (D150, D151, D157) ---
_K = ["origin", "style_color"]
_WF = pd.read_parquet("data/weather_event_feats.parquet"); _WE = [c for c in _WF.columns if c not in _K + ["t_tgt_real", "ta_tgt"]]
_BK = pd.read_parquet("data/basket_feats_cp.parquet")[_K + ["nb_sea4", "nb_lvl"]].rename(columns={"nb_sea4": "cp_nb_sea4", "nb_lvl": "cp_nb_lvl"})
import glob as _g
_L = pd.concat([pd.read_csv(p) for p in sorted(_g.glob("data/llm/scores_part*.csv"))]).drop_duplicates("style_color"); _LL = [c for c in _L.columns if c != "style_color"]
T1 = T1.merge(_BK, on=_K, how="left").merge(_L, on="style_color", how="left").merge(_WF[_K + _WE], on=_K, how="left")
_NEW = ["cp_nb_sea4", "cp_nb_lvl"] + _LL + _WE; BASE += _NEW; FULL += _NEW

def fit_q(tr, te):
    out = np.zeros((len(te), len(QS)))
    for cols in (BASE, FULL):
        for j, q in enumerate(QS):
            m = lgb.LGBMRegressor(objective="quantile", alpha=q, **P).fit(tr[cols], tr.z)
            out[:, j] += m.predict(te[cols]) / 2
    return np.sort(out, axis=1)                                     # no crossing

if __name__ == "__main__":
    BT = pd.read_parquet("data/best_backtest_preds.parquet").groupby(["origin", "style_color"], as_index=False).pred.sum().rename(columns={"pred": "point"})
    rows, t0 = [], time.time()
    for o in [str(p) for p in pd.period_range("2025-02", "2026-02", freq="M")]:
        oo = pd.Period(o).ordinal
        tr = T1[(T1.o_ord + 4 <= oo) & T1.ytot.notna()]; te = T1[T1.origin == o]
        zq = fit_q(tr, te)
        R = te[["origin", "style_color", "level", "age_m", "ytot"]].copy()
        for j, q in enumerate(QS): R[f"q{int(q*100):02d}"] = np.clip((4 * te.level.values + 1) * np.exp(zq[:, j]) - 1, 0, None)
        rows.append(R); print(o, "train rows", len(tr), "items", len(te), round(time.time() - t0), "s", flush=True)
    Q = pd.concat(rows).merge(BT, on=["origin", "style_color"], how="left")
    Q.to_parquet("data/q_backtest_wx_rerun.parquet")
    print("saved", Q.shape)
